// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpTime, uint256 blockNumDelay) public {
        vm.assume(amount > 0);
        vm.assume(warpTime > 0);
        vm.assume(blockNumDelay >= 0);

        vm.warp(warpTime);
        vm.roll(block.number + blockNumDelay);

        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success,) = address(c).call{value: amount}("");
        if (success) {
            assertTrue(c.pastBlockTime() == block.timestamp + 1 ? amount == 10 ether : true);
        }
    }
}
